{"cards": [{"node_code": "N_e5bff999b7f579a2", "definition": "研究船闸工程结构（如闸室、闸门、启闭机基础）所采用的建筑材料、结构材料及其性能、选用原则、耐久性要求及在船闸特定环境下的应用。", "boundary": "本节点聚焦于船闸工程实体结构使用的材料。边界在于区分“材料”与“结构构造”（构造侧重几何形状与连接方式，材料侧重物质属性）；区分“船闸材料”与“通用土木工程材料”（本节点侧重船闸高水位差、动水压力、腐蚀等特殊工况下的材料选择与性能要求）。若内容涉及材料的基础物理化学性质研究，主挂载本节点；若涉及材料在结构中的具体配筋或连接构造，主挂载船闸尺度与构造。", "includes": ["船闸混凝土、钢材、闸门金属结构材料的性能与选用", "船闸材料在动水、腐蚀、冻融等环境下的耐久性研究", "船闸新型工程材料的应用与试验"], "excludes": ["船闸结构的具体几何尺寸与配筋构造", "船闸施工过程中的材料加工工艺（归入施工）", "船闸水力学计算"], "sibling_distinctions": [{"other_code": "N_c6f8747d523e21a1", "rule": "本节点侧重材料本身的属性、性能及选用；船闸尺度与构造侧重结构的空间布局、尺寸确定及构件连接方式。"}, {"other_code": "N_6cfb5a48afeae9f6", "rule": "本节点侧重材料的设计选型与性能要求；船闸施工侧重材料在现场的加工、安装、浇筑及质量控制过程。"}], "cross_boundary_rule": "若内容涉及材料在船闸结构中的具体构造做法（如钢筋绑扎、止水带安装），主挂载船闸尺度与构造；若侧重材料本身的性能测试或选型标准，主挂载本节点。"}, {"node_code": "N_6cfb5a48afeae9f6", "definition": "研究船闸工程从基础开挖、主体结构浇筑、金属结构安装到调试运行的施工方法、工艺、技术措施、质量控制及安全管理。", "boundary": "本节点聚焦于船闸工程的“建造过程”。边界在于区分“施工”与“设计”（设计侧重方案与计算，施工侧重实现）；区分“施工”与“运行”（施工侧重建成前，运行侧重建成后）。若内容涉及船闸施工中的特殊水文地质处理、大型构件吊装、水下施工等技术，主挂载本节点。若涉及施工后的长期维护，归入养护与维修。", "includes": ["船闸基础处理、闸室及上下游连接段施工技术与工艺", "船闸金属结构（闸门、启闭机）安装与调试技术", "船闸施工质量控制、安全监测及特殊工况下的施工措施"], "excludes": ["船闸规划设计理论与计算", "船闸建成后的日常运行调度与管理", "船闸结构材料的实验室性能研究"], "sibling_distinctions": [{"other_code": "N_12164e8112d75d6c", "rule": "本节点侧重工程实施过程中的技术与方法；规划与设计侧重工程前期的方案比选、水力计算及结构设计。"}, {"other_code": "N_3055600593e4073a", "rule": "本节点侧重工程建成前的施工建造；运行及管理侧重工程建成后的船舶过闸调度、设备操作及日常维护。"}], "cross_boundary_rule": "若内容涉及施工阶段的结构监测数据用于指导施工调整，主挂载本节点；若涉及运行阶段的结构安全监测，主挂载运行及管理或养护与维修。"}, {"node_code": "N_d6a76bfbe855ae6c", "definition": "研究不同类型船闸（如单级/多级、单向/双向、垂直升船机除外、内河/海洋、特殊用途船闸）的结构形式、特点、适用条件及典型工程案例。", "boundary": "本节点聚焦于船闸的“类型学”与“分类”。边界在于区分“各种船闸”与“船闸尺度与构造”（本节点侧重类型划分与整体特征，构造侧重具体构件细节）；区分“各种船闸”与“规划与设计”（本节点侧重既有类型的归纳，设计侧重新工程的方案制定）。若内容涉及某类特定船闸（如升船机虽在兄弟节点，但此处指非升船机的各类闸）的结构特点比较，主挂载本节点。", "includes": ["按级数、方向、用途、水域等分类的船闸类型及其结构特点", "各类船闸的适用条件、优缺点比较及典型工程实例", "特殊船闸（如双向船闸、多级船闸）的总体布置与工作原理"], "excludes": ["船闸通用的水力学计算理论（归入水力学理论）", "船闸具体的施工工艺流程（归入施工）", "船闸运行调度规则（归入运行及管理）"], "sibling_distinctions": [{"other_code": "N_c6f8747d523e21a1", "rule": "本节点侧重船闸类型的宏观分类与整体结构特征；船闸尺度与构造侧重具体构件（如闸墙、底板、闸门）的尺寸确定与细部构造。"}, {"other_code": "N_12164e8112d75d6c", "rule": "本节点侧重对已有船闸类型的归纳与特征描述；规划与设计侧重针对具体工程项目的方案论证、水力计算与设计参数确定。"}], "cross_boundary_rule": "若内容涉及某类船闸的具体设计计算过程，主挂载规划与设计；若侧重该类船闸的结构形式比较与特点总结，主挂载本节点。"}]}
